### **Example of the Updated Components:**

#### **Full Updated `AppleLoginButton` Component:**

```javascript
import React, { useState } from "react";
import { Alert } from "react-native";
import {
  AppleError,
  appleAuth,
} from "@invertase/react-native-apple-authentication";
import CONFIG from "@/core/CONFIG";
import axios from "axios";
import IconButton from "@/components/SigninButtons/IconButton";
import { useRouter } from "expo-router";
import { useSession } from "@/core/session/AuthContext";

async function appleSignInRequest(): Promise<any> {
  try {
    const response = await appleAuth.performRequest({
      requestedOperation: appleAuth.Operation.LOGIN,
      requestedScopes: [appleAuth.Scope.FULL_NAME, appleAuth.Scope.EMAIL],
    });

    const credentialState = await appleAuth.getCredentialStateForUser(response.user);

    if (credentialState === appleAuth.State.AUTHORIZED) {
      return response; // Return the full response
    }

    console.log("[Apple Sign In] Authentication failed. Original response: ", {
      response,
    });
  } catch (error) {
    console.log("[Apple Sign In] Request failed:", error);
  }
}

function AppleLoginButton() {
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();
  const { signIn } = useSession();

  const handlePress = async () => {
    setIsLoading(true);
    try {
      const response = await appleSignInRequest();
      if (!response || !response.identityToken) {
        setIsLoading(false);
        return;
      }
      const token = response.identityToken;
      const userIdentifier = response.user;
      const email = response.email;
      const fullName = response.fullName;

      const postData = {
        access_token: token,
        code: token,
        user: userIdentifier,
        email: email,
        full_name: fullName,
      };

      const axiosConfig = {
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
      };

      const authToken = await axios.post(
        CONFIG.APPLE_SIGN_IN.WEB_CALLBACK_URL,
        postData,
        axiosConfig,
      );

      if (authToken?.data?.data) {
        await signIn(authToken?.data?.data);
        router.replace("/");
      }
    } catch (error: AppleError | any) {
      if (error.code === appleAuth.Error.CANCELED) {
        console.log("[Apple Sign In] İşlem iptal edildi.");
      } else {
        console.error("Apple Sign In failed:", error);
        Alert.alert("Error", error?.response?.data?.message || "Server Error");
      }
    } finally {
      setIsLoading(false);
    }
  };

  if (!appleAuth.isSupported) {
    return null;
  }

  return (
    <IconButton
      onPress={handlePress}
      isLoading={isLoading}
      provider={CONFIG.SIGN_IN_METHOD.APPLE}
      variant="viewLight"
    />
  );
}

AppleLoginButton.displayName = "AppleLoginButton";

export default AppleLoginButton;
```

